import { createContext, useContext } from 'react';
import { useWallet } from '../hooks/useWallet';

const WalletContext = createContext(null);

export function WalletProvider({ children }) {
  const { provider, signer, address, connect, disconnect, isConnected, error } = useWallet();
  return (
    <WalletContext.Provider value={{ provider, signer, address, connect, disconnect, isConnected, error }}>
      {children}
    </WalletContext.Provider>
  );
}

export function useWalletContext() {
  const ctx = useContext(WalletContext);
  if (!ctx) {
    throw new Error('useWalletContext must be used within WalletProvider');
  }
  return ctx;
}

import { useState, useCallback, useEffect } from 'react';
import { BrowserProvider } from 'ethers';
import { CONTRACTS, CHAIN_ID, CHAIN_NAME } from '../contracts/config';

const QITMEER_RPC = 'https://qng.rpc.qitmeer.io';

export function useWallet() {
  const [provider, setProvider] = useState(null);
  const [signer, setSigner] = useState(null);
  const [address, setAddress] = useState(null);
  const [balance, setBalance] = useState(null);
  const [connecting, setConnecting] = useState(false);
  const [error, setError] = useState(null);

  const refreshBalance = useCallback(async (web3Provider, addr) => {
    if (!web3Provider || !addr) return;
    try {
      const balanceWei = await web3Provider.getBalance(addr);
      setBalance(Number(balanceWei) / 1e18);
    } catch (e) {
      console.error('refreshBalance failed:', e);
    }
  }, []);

  const connect = useCallback(async () => {
    setConnecting(true);
    setError(null);
    try {
      if (!window.ethereum) {
        throw new Error('No wallet detected. Please install MetaMask or a Qitmeer-compatible wallet.');
      }
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      if (!accounts || accounts.length === 0) {
        throw new Error('No accounts found. Please unlock your wallet.');
      }
      const addr = accounts[0];
      const web3Provider = new BrowserProvider(window.ethereum);
      const web3Signer = await web3Provider.getSigner();
      const network = await web3Provider.getNetwork();
      if (Number(network.chainId) !== CHAIN_ID) {
        console.warn(`Connected to chain ${network.chainId}, expected ${CHAIN_ID} (${CHAIN_NAME})`);
      }
      await refreshBalance(web3Provider, addr);
      setProvider(web3Provider);
      setSigner(web3Signer);
      setAddress(addr);
      console.log('Wallet connected:', addr);
    } catch (err) {
      console.error('Wallet connection error:', err);
      setError(err.message || 'Failed to connect wallet');
    } finally {
      setConnecting(false);
    }
  }, [refreshBalance]);

  const disconnect = useCallback(() => {
    if (window.ethereum?.removeAllListeners) {
      try { window.ethereum.removeAllListeners(); } catch (e) {}
    }
    setProvider(null);
    setSigner(null);
    setAddress(null);
    setBalance(null);
    setError(null);
  }, []);

  const switchToQitmeer = useCallback(async () => {
    if (!window.ethereum) return;
    const chainIdHex = '0x' + CHAIN_ID.toString(16);
    try {
      await window.ethereum.request({ method: 'wallet_switchEthereumChain', params: [{ chainId: chainIdHex }] });
    } catch (switchError) {
      if (switchError.code === 4902) {
        try {
          await window.ethereum.request({
            method: 'wallet_addEthereumChain',
            params: [{
              chainId: chainIdHex,
              chainName: CHAIN_NAME,
              rpcUrls: [QITMEER_RPC],
              blockExplorerUrls: ['https://qng.meerscan.io'],
              nativeCurrency: { name: 'MEER', symbol: 'MEER', decimals: 18 },
            }],
          });
        } catch (addError) {
          console.error('Failed to add Qitmeer chain:', addError);
        }
      }
    }
  }, []);

  useEffect(() => {
    if (!window.ethereum) return;
    const handleAccountsChanged = (accounts) => {
      if (accounts.length === 0) {
        disconnect();
      } else {
        setAddress(accounts[0]);
        if (provider) refreshBalance(provider, accounts[0]);
      }
    };
    const handleChainChanged = () => {
      if (provider) refreshBalance(provider, address).catch(() => {});
    };
    window.ethereum.on('accountsChanged', handleAccountsChanged);
    window.ethereum.on('chainChanged', handleChainChanged);
    return () => {
      window.ethereum.removeListener('accountsChanged', handleAccountsChanged);
      window.ethereum.removeListener('chainChanged', handleChainChanged);
    };
  }, [provider, address, disconnect, refreshBalance]);

  return {
    provider, signer, address, balance, connecting, error,
    connect, disconnect, switchToQitmeer, isConnected: !!address,
  };
}

import { useRef, useEffect, useState } from 'react';
import { checkVersionCompatibility, ALPHA_7_CONSTRAINT } from '../utils/versionCompat';

const CURRENT_ECHO_VERSION = '1.1.0';
const API_BASE = 'https://echo-api.meerfans.club';

const PHASE_NAMES = ['纳相', '展相', '照相', '议相', '决相', '映相'];
const PHASES = PHASE_NAMES.map((name, shiPosition) => ({
  name,
  desc: ['争议受理', '证据展示', '观点对照', '群体审议', '共识裁决', '结果映现'][shiPosition],
  shiPosition,
}));

function PotentialChart({ history }) {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !history || history.length === 0) return;
    const parent = canvas.parentElement;
    if (!parent) return;
    const w = parent.clientWidth;
    const h = 112;
    canvas.width = w * 2;
    canvas.height = h * 2;
    canvas.style.width = w + 'px';
    canvas.style.height = h + 'px';
    const ctx = canvas.getContext('2d');
    ctx.scale(2, 2);
    ctx.clearRect(0, 0, w, h);

    const values = history.map(h => h.potential || h.potentialValue || 0);
    const max = Math.max(...values, 0.01);
    const min = Math.min(...values, 0);
    const range = max - min || 0.01;

    // 淡墨网格
    ctx.strokeStyle = 'rgba(168,163,154,0.2)';
    ctx.lineWidth = 0.5;
    for (let i = 1; i < 5; i++) {
      const y = (i / 5) * h;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }

    // 心电图折线 - 朱砂色
    ctx.beginPath();
    ctx.strokeStyle = '#c45c48';
    ctx.lineWidth = 2;
    values.forEach((v, i) => {
      const x = (i / (values.length - 1)) * w;
      const y = (1 - (v - min) / range) * h;
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 节点圆点
    values.forEach((v, i) => {
      const x = (i / (values.length - 1)) * w;
      const y = (1 - (v - min) / range) * h;
      ctx.beginPath();
      ctx.fillStyle = '#c45c48';
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });

    // 数据点标注
    if (values.length <= 10) {
      ctx.fillStyle = '#78716c';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      values.forEach((v, i) => {
        const x = (i / (values.length - 1)) * w;
        const y = (1 - (v - min) / range) * h;
        ctx.fillText(v.toFixed(2), x, y - 8);
      });
    }
  }, [history]);

  return (
    <div className="w-full h-28">
      <canvas ref={canvasRef} className="w-full h-full bg-[#faf9f7] rounded" />
    </div>
  );
}

function EdgeList({ edges }) {
  if (!edges || edges.length === 0) return <div className="text-[#6b6b6b]">无边数据</div>;
  return (
    <div className="space-y-2">
      {edges.map((e, i) => {
        const compat = e.versionConstraint
          ? checkVersionCompatibility(CURRENT_ECHO_VERSION, e.versionConstraint)
          : checkVersionCompatibility(CURRENT_ECHO_VERSION, ALPHA_7_CONSTRAINT);
        return (
          <div key={i} className={`bg-[#faf9f7] rounded border p-3 text-sm ${compat?.compatible === false ? 'border-red-300' : 'border-[#e5e2dc]'}`}>
            <div className="flex justify-between mb-1">
              <span className="text-[#6b6b6b]">{e.fromNode?.slice(0,8) || '?'}… → {e.toNode?.slice(0,8) || '?'}…</span>
              {compat && (
                <span className={`text-xs ${compat.compatible ? 'text-emerald-600' : 'text-red-500'}`}>
                  {compat.compatible ? '✅ 兼容' : `❌ ${compat.reason}`}
                </span>
              )}
            </div>
            {e.versionConstraint ? (
              <div className="text-xs text-[#c45c48]">
                v{e.versionConstraint.minVersion}~v{e.versionConstraint.maxVersion}
                <span className="text-[#6b6b6b] ml-2">({e.versionConstraint.constraintType})</span>
                <span className="text-[#9a9a9a] ml-2">blk#{e.versionConstraint.declaredAtBlock}</span>
              </div>
            ) : (
              <div className="text-xs text-[#9a9a9a]">v1.0.0~v2.0.0 (ALPHA-7 默认约束)</div>
            )}
          </div>
        );
      })}
    </div>
  );
}

