// ECHO v2 数据契约 — 单一真理源
// 与 backend/echo-data-api.js 锁定的字段；任何不一致必须改这里，并通知 Seaman_bot 后端同步

// ============================================================
// 后端原始字段（可能缺失/类型不固定）→ 归一化后字段（前端稳定消费）
// ============================================================

/**
 * @typedef {Object} NormalizedNode
 * @property {string} nodeId           32 字节 hex
 * @property {string} creator          钱包地址
 * @property {number} potential        势位（归一化为数字，0 默认）
 * @property {number} phase            相位 0-5（0=纳相, 默认 0）
 * @property {number} outDegree        出度
 * @property {number} inDegree         入度
 * @property {FourRights} fourRights   四权 {usage, derive, expand, benefit}
 * @property {PotentialPoint[]} potentialHistory 势位历史
 * @property {EdgeRef[]} edges         出边引用
 * @property {number} createdAtBlock
 * @property {string} txHash
 * @property {number} timestamp        创建时间（秒）
 * @property {number} u                四权数字映射（备查）
 * @property {number} d
 * @property {number} e
 * @property {number} b
 * @property {FourRights} quadrants    四权（部分节点只返这个）
 */

/**
 * @typedef {Object} PotentialPoint
 * @property {number} timestamp   毫秒
 * @property {number} potential   势值
 * @property {number} phase
 * @property {number} block
 */

/**
 * @typedef {Object} EdgeRef
 * @property {string} toNode
 * @property {number} depth
 * @property {string} declarer
 * @property {number} edgeType
 */

/**
 * @typedef {Object} FourRights
 * @property {number} usage
 * @property {number} derive
 * @property {number} expand
 * @property {number} benefit
 */

/**
 * @typedef {Object} Edge
 * @property {string} fromNode
 * @property {string} toNode
 * @property {string} declarer
 * @property {number} depth
 * @property {number} timestamp
 * @property {number} declaredAtBlock
 * @property {string} txHash
 * @property {string} versionConstraint
 */

/**
 * @typedef {Object} Round
 * @property {number} roundId
 * @property {string} question
 * @property {string[]} options
 * @property {number} startTime
 * @property {number} endTime
 * @property {string} totalPool
 * @property {number} winningOption
 * @property {boolean} settled
 * @property {string} creator
 */

/**
 * @typedef {Object} Milestone
 * @property {string|number} id
 * @property {string} title
 * @property {string} date
 * @property {string} note
 * @property {string} branch
 */

// ============================================================
// 归一化工具 — 把后端不稳定的字段映射成 NormalizedNode
// ============================================================

const PHASE_DEFAULT = 0;

/**
 * 把后端任意节点对象归一化为 NormalizedNode
 * 处理 potential/phase/fourRights 字段名漂移问题
 * @param {any} raw
 * @returns {NormalizedNode}
 */
export function normalizeNode(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const fr = raw.fourRights || raw.quadrants || {};
  return {
    nodeId: raw.nodeId || '',
    creator: raw.creator || '',
    potential: toNumber(raw.potential ?? raw.potentialValue, 0),
    phase: toNumber(raw.phase, PHASE_DEFAULT),
    outDegree: toNumber(raw.outDegree, 0),
    inDegree: toNumber(raw.inDegree, 0),
    fourRights: {
      usage: toNumber(fr.usage, 0),
      derive: toNumber(fr.derive, 0),
      expand: toNumber(fr.expand, 0),
      benefit: toNumber(fr.benefit, 0),
    },
    potentialHistory: Array.isArray(raw.potentialHistory)
      ? raw.potentialHistory
          .map(p => ({
            timestamp: toNumber(p.timestamp, 0),
            potential: toNumber(p.potential ?? p.potentialValue, 0),
            phase: toNumber(p.phase, PHASE_DEFAULT),
            block: toNumber(p.block, 0),
          }))
          .filter(p => p.timestamp > 0)
      : [],
    edges: Array.isArray(raw.edges)
      ? raw.edges.map(e => ({
          toNode: e.toNode || '',
          depth: toNumber(e.depth, 0),
          declarer: e.declarer || '',
          edgeType: toNumber(e.edgeType, 0),
        }))
      : [],
    createdAtBlock: toNumber(raw.createdAtBlock, 0),
    txHash: raw.txHash || '',
    timestamp: toNumber(raw.timestamp, 0),
    u: toNumber(raw.u, 0),
    d: toNumber(raw.d, 0),
    e: toNumber(raw.e, 0),
    b: toNumber(raw.b, 0),
    quadrants: {
      usage: toNumber(fr.usage, 0),
      derive: toNumber(fr.derive, 0),
      expand: toNumber(fr.expand, 0),
      benefit: toNumber(fr.benefit, 0),
    },
  };
}

/** 归一化 edge 列表 */
export function normalizeEdges(rawList) {
  if (!Array.isArray(rawList)) return [];
  return rawList.map(e => ({
    fromNode: e.fromNode || '',
    toNode: e.toNode || '',
    declarer: e.declarer || '',
    depth: toNumber(e.depth, 0),
    timestamp: toNumber(e.timestamp, 0),
    declaredAtBlock: toNumber(e.declaredAtBlock, 0),
    txHash: e.txHash || '',
    versionConstraint: e.versionConstraint || 'direct-derivation',
  }));
}

/** 归一化 round */
export function normalizeRound(raw) {
  if (!raw) return null;
  return {
    roundId: toNumber(raw.roundId, 0),
    question: raw.question || '',
    options: Array.isArray(raw.options) ? raw.options : [],
    startTime: toNumber(raw.startTime, 0),
    endTime: toNumber(raw.endTime, 0),
    totalPool: raw.totalPool ?? '0.0',
    winningOption: toNumber(raw.winningOption, -1),
    settled: !!raw.settled,
    creator: raw.creator || '',
  };
}

// ============================================================
// 内部工具
// ============================================================

function toNumber(v, fallback) {
  if (v === null || v === undefined) return fallback;
  if (typeof v === 'number') return Number.isFinite(v) ? v : fallback;
  if (typeof v === 'string') {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  }
  return fallback;
}

// ============================================================
// 业务常量 — 和后端约定
// ============================================================

export const PHASE_NAMES = ['纳相', '展相', '照相', '议相', '决相', '映相'];
export const PHASE_DESCS = ['争议受理', '证据展示', '观点对照', '群体审议', '共识裁决', '结果映现'];

/** 4 印（契）— 顺序与 DianPage 渲染顺序保持一致 */
export const FOUR_SEALS = [
  { key: 'usage',     name: '流布印', desc: '一灯传万灯',   detail: '照临无界，复制、传播、展示' },
  { key: 'derive',    name: '化裁印', desc: '穷则变，变则通', detail: '翻译、改编、二次创作' },
  { key: 'expand',    name: '衍义印', desc: '枝蔓滋长',     detail: '续作、外传、同人' },
  { key: 'reproduce', name: '重光印', desc: '旧命新辉',     detail: '重制、汇编、数据库' },
];

/** 推断 4 印在链上是否启用 — 当前没有专门的开关字段，按 fourRights 是否 > 0 启发式判断 */
export function isSealEnabled(node, sealKey) {
  if (!node || !node.fourRights) return false;
  // 注：reproduce 字段不在 fourRights 标准 4 项里（只有 u/d/e/b），
  // 这里按 'expand' 复用作为重光印的开关
  const map = { usage: 'usage', derive: 'derive', expand: 'expand', reproduce: 'benefit' };
  const field = map[sealKey] || sealKey;
  return toNumber(node.fourRights[field], 0) > 0;
}

// ECHO v2 API 客户端 — 统一 base URL、超时、错误处理
// 所有页面必须通过此模块访问后端，禁止硬编码域名

const DEFAULT_TIMEOUT_MS = 8000;

function getBase() {
  // vite 会把 import.meta.env.VITE_API_BASE 注入
  const base = import.meta.env.VITE_API_BASE;
  if (!base) {
    console.warn('[api] VITE_API_BASE 未设置，回退到默认值');
    return 'https://echo-api.meerfans.club';
  }
  return base.replace(/\/+$/, ''); // 去掉末尾斜杠
}

/**
 * @param {string} path
 * @param {RequestInit & {timeoutMs?: number}} [opts]
 */
export async function apiGet(path, opts = {}) {
  const ctrl = new AbortController();
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);

  const url = getBase() + (path.startsWith('/') ? path : '/' + path);

  try {
    const res = await fetch(url, {
      ...opts,
      signal: ctrl.signal,
      headers: { Accept: 'application/json', ...(opts.headers || {}) },
    });
    clearTimeout(timer);
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      throw new Error(`HTTP ${res.status}${text ? `: ${text.slice(0, 200)}` : ''}`);
    }
    return res.json();
  } catch (err) {
    clearTimeout(timer);
    if (err.name === 'AbortError') {
      throw new Error(`请求超时（${timeoutMs}ms）：${path}`);
    }
    throw err;
  }
}

export const API_BASE = getBase();

// ============================================================
// 端点封装 — 每个函数对应一个后端 endpoint，返回归一化后的数据
// ============================================================

import { normalizeNode, normalizeEdges, normalizeRound } from '../contracts/types';

/** GET /api/potential — 势位场快照（含节点+历史） */
export async function fetchPotential(timeoutMs) {
  const data = await apiGet('/api/potential', { timeoutMs });
  const nodes = Array.isArray(data?.nodes) ? data.nodes.map(normalizeNode).filter(Boolean) : [];
  return { nodes, updatedAt: data?.updatedAt || Date.now() };
}

/** GET /api/nodes — 节点列表 */
export async function fetchNodes(timeoutMs) {
  const data = await apiGet('/api/nodes', { timeoutMs });
  const nodes = Array.isArray(data?.nodes) ? data.nodes.map(normalizeNode).filter(Boolean) : [];
  return { nodes, total: data?.total ?? nodes.length, updatedAt: data?.updatedAt };
}

/** GET /api/edges — 边列表 */
export async function fetchEdges(timeoutMs) {
  const data = await apiGet('/api/edges', { timeoutMs });
  const edges = normalizeEdges(data?.edges);
  return { edges, total: data?.total ?? edges.length, updatedAt: data?.updatedAt };
}

/** GET /api/game/rounds — 对战回合列表（势位榜从 rounds 聚合更真实） */
export async function fetchRounds(timeoutMs) {
  const data = await apiGet('/api/game/rounds', { timeoutMs });
  const rounds = Array.isArray(data?.rounds) ? data.rounds.map(normalizeRound).filter(Boolean) : [];
  return { rounds, total: data?.total ?? rounds.length, updatedAt: data?.updatedAt };
}

/** GET /api/game/round/:id — 单个回合详情 */
export async function fetchRound(id, timeoutMs) {
  const data = await apiGet(`/api/game/round/${id}`, { timeoutMs });
  return { round: normalizeRound(data?.round), bets: data?.bets || [], betCount: data?.betCount || 0 };
}

/** GET /api/game/stats — 战斗统计 */
export async function fetchGameStats(timeoutMs) {
  const data = await apiGet('/api/game/stats', { timeoutMs });
  return data?.stats || {};
}

/** GET /api/health — 健康检查 */
export async function fetchHealth(timeoutMs = 4000) {
  return apiGet('/api/health', { timeoutMs });
}

