  return <button onClick={connect} className="text-xs bg-[#6B9E87] text-white px-3 py-1.5 rounded hover:bg-[#5a8a76] transition-colors">连接钱包</button>;
}

import { Component } from 'react';

export default class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, info) {
    console.error('ErrorBoundary caught:', error, info);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#FAF9F7] text-[#2D2A26] flex items-center justify-center p-8">
          <div className="bg-white border border-[#E5E2DC] rounded-lg p-6 max-w-md">
            <h2 className="text-xl font-bold text-[#C46B6B] mb-2">系统异常</h2>
            <p className="text-[#6B665C] text-sm mb-4">合约调用或渲染过程中发生错误，请刷新重试。</p>
            <pre className="text-xs text-[#C46B6B] bg-[#F2F0ED] p-3 rounded overflow-auto">{this.state.error?.message}</pre>
            <button onClick={() => window.location.reload()} className="mt-4 text-sm border border-[#E5E2DC] px-3 py-1.5 rounded hover:border-[#2D2A26] transition-colors">刷新页面</button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

// ECHO 协议 — 边版本约束兼容性检查

function parseSemver(v) {
  if (!v || typeof v !== 'string') return null;
  const m = v.match(/^(\d+)(?:\.(\d+))?(?:\.(\d+))?/);
  if (!m) return null;
  return {
    major: parseInt(m[1], 10) || 0,
    minor: parseInt(m[2], 10) || 0,
    patch: parseInt(m[3], 10) || 0,
  };
}

function compareSemver(a, b) {
  const av = parseSemver(a);
  const bv = parseSemver(b);
  if (!av || !bv) return 0;
  if (av.major !== bv.major) return av.major - bv.major;
  if (av.minor !== bv.minor) return av.minor - bv.minor;
  return av.patch - bv.patch;
}

export function checkVersionCompatibility(currentVersion, constraint) {
  if (!currentVersion || !constraint) {
    return { compatible: false, reason: '版本或约束为空' };
  }

  const cv = parseSemver(currentVersion);
  if (!cv) {
    return { compatible: false, reason: `当前版本 ${currentVersion} 无法解析` };
  }

  const { minVersion, maxVersion, constraintType = 'range' } = constraint;

  // exact
  if (constraintType === 'exact') {
    if (compareSemver(currentVersion, minVersion) === 0) {
      return { compatible: true };
    }
    return { compatible: false, reason: `要求精确版本 ${minVersion}，当前 ${currentVersion}` };
  }

  // min-only
  if (constraintType === 'min-only') {
    if (minVersion && compareSemver(currentVersion, minVersion) < 0) {
      return { compatible: false, reason: `最低要求 ${minVersion}，当前 ${currentVersion}` };
    }
    return { compatible: true };
  }

  // max-only
  if (constraintType === 'max-only') {
    if (maxVersion && compareSemver(currentVersion, maxVersion) > 0) {
      return { compatible: false, reason: `最高允许 ${maxVersion}，当前 ${currentVersion}` };
    }
    return { compatible: true };
  }

  // range (default)
  if (minVersion && compareSemver(currentVersion, minVersion) < 0) {
    return { compatible: false, reason: `最低要求 ${minVersion}，当前 ${currentVersion}` };
  }
  if (maxVersion && compareSemver(currentVersion, maxVersion) > 0) {
    return { compatible: false, reason: `最高允许 ${maxVersion}，当前 ${currentVersion}` };
  }
  return { compatible: true };
}

export const ALPHA_7_CONSTRAINT = {
  minVersion: '1.0.0',
  maxVersion: '2.0.0',
  constraintType: 'range',
  declaredAtBlock: 2704473,
  label: 'ALPHA-7 边伦理承诺',
};

export function checkAlpha7Compatibility(currentVersion) {
  return checkVersionCompatibility(currentVersion, ALPHA_7_CONSTRAINT);
}

import { useState, useCallback, useRef } from 'react';
import { Contract, keccak256, solidityPacked } from 'ethers';
import { CONTRACTS } from '../contracts/config';
import { AGENTJURY_ABI } from '../contracts/abi';

const { AgentJury } = CONTRACTS;

export function useCase(signer) {
  const [currentCase, setCurrentCase] = useState(null);
  const [commitments, setCommitments] = useState({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const processingRef = useRef(false);

  const loadCase = useCallback(async (caseId) => {
    if (!signer) { setError('Wallet not connected'); return; }
    if (processingRef.current) return;
    processingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);
      const caseData = await jury.getCase(caseId);
      const [evidenceHash, commitDeadline, revealDeadline, state, commitCount, revealCount, jurorCount, resolved, appealed] = caseData;
      setCurrentCase({
        caseId,
        evidenceHash,
        commitDeadline: Number(commitDeadline),
        revealDeadline: Number(revealDeadline),
        state: Number(state),
        commitCount: Number(commitCount),
        revealCount: Number(revealCount),
        jurorCount: Number(jurorCount),
        resolved,
        appealed,
      });
    } catch (err) {
      console.error('Failed to load case:', err);
      setError(err.message || 'Failed to load case');
    } finally {
      setLoading(false);
      processingRef.current = false;
    }
  }, [signer]);

  const commitVote = useCallback(async (caseId, vote, salt) => {
    if (!signer) { setError('Wallet not connected'); return; }
    if (processingRef.current) return;
    processingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);
      const address = await signer.getAddress();
      const commitHash = keccak256(solidityPacked(['bool', 'uint256', 'uint256', 'address'], [vote, BigInt(salt), caseId, address]));
      const tx = await jury.juryCommit(caseId, commitHash, BigInt(salt));
      const receipt = await tx.wait();
      setCommitments(prev => ({ ...prev, [caseId]: commitHash }));
      return receipt;
    } catch (err) {
      console.error('Commit failed:', err);
      setError(err.message || 'Commit failed');
    } finally {
      setLoading(false);
      processingRef.current = false;
    }
  }, [signer]);

  const revealVote = useCallback(async (caseId, vote, salt) => {
    if (!signer) { setError('Wallet not connected'); return; }
    if (processingRef.current) return;
    processingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);
      const tx = await jury.juryReveal(caseId, vote, BigInt(salt));
      const receipt = await tx.wait();
      return receipt;
    } catch (err) {
      console.error('Reveal failed:', err);
      setError(err.message || 'Reveal failed');
    } finally {
      setLoading(false);
      processingRef.current = false;
    }
  }, [signer]);

  const finalizeCase = useCallback(async (caseId) => {
    if (!signer) { setError('Wallet not connected'); return; }
    if (processingRef.current) return;
    processingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);
      const tx = await jury.finalizeCase(caseId);
      const receipt = await tx.wait();
      return receipt;
    } catch (err) {
      console.error('Finalize failed:', err);
      setError(err.message || 'Finalize failed');
    } finally {
      setLoading(false);
      processingRef.current = false;
    }
  }, [signer]);

  return {
    currentCase, commitments, loading, error,
    loadCase, commitVote, revealVote, finalizeCase,
  };
}

